import{dynasties}from"../data.js";export function DynastyMap(){const n=document.createElement("div");n.className="dynasty-map-container",n.innerHTML=`\n    <h3 class="section-subtitle">Dynasty Territories</h3>\n    <div class="dynasty-map-wrapper">\n      <div class="india-map">\n        <svg viewBox="0 0 400 500" class="india-outline">\n          <path d="M200,20 L260,50 L300,80 L320,120 L340,160 L350,200 L360,240 L370,280 L360,320 L340,360 L310,400 L280,430 L250,460 L220,480 L200,490 L180,480 L150,460 L120,430 L90,400 L70,360 L50,320 L40,280 L45,240 L55,200 L70,160 L90,120 L120,80 L160,50 Z"\n                fill="none" stroke="currentColor" stroke-width="2" opacity="0.3"/>\n        </svg>\n        ${dynasties.map(n=>`\n          <div class="map-marker" style="top:${n.mapPosition.top};left:${n.mapPosition.left};--marker-color:${n.color}"\n               data-dynasty="${n.id}" title="${n.name} (${n.period})">\n            <span class="marker-dot"></span>\n            <span class="marker-label">${n.name.split(" ")[0]}</span>\n          </div>\n        `).join("")}\n      </div>\n      <div class="map-legend">\n        ${dynasties.map(n=>`\n          <div class="legend-item" data-dynasty="${n.id}">\n            <span class="legend-color" style="background:${n.color}"></span>\n            <span class="legend-name">${n.name}</span>\n            <span class="legend-period">${n.period}</span>\n          </div>\n        `).join("")}\n      </div>\n    </div>\n  `;return n.querySelectorAll(".map-marker").forEach(n=>{n.addEventListener("click",()=>{const a=n.dataset.dynasty,e=dynasties.find(n=>n.id===a);if(!e)return;const s=document.createElement("div");s.className="map-popup",s.innerHTML=`\n        <h4 style="color:${e.color}">${e.name}</h4>\n        <p class="popup-period">${e.period}</p>\n        <p class="popup-capital">Capital: ${e.capital}</p>\n        <p class="popup-territory">Territory: ${e.territory}</p>\n      `,n.appendChild(s);const t=()=>{s.remove()};s.addEventListener("click",n=>{n.stopPropagation(),t()}),setTimeout(()=>document.addEventListener("click",t,{once:!0}),10)})}),n}